CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.harbour_performance_metrics
COMMENT 'The second insurer''s motor loss ratio on the same definition as Bricksurance''s motor_performance_metrics (paid plus outstanding case reserves plus IBNR, net of recoveries, over EARNED premium; accident-quarter basis; GBP), computed from the conformed views that two mapping files produce over Harbour Mutual''s policy centre and claim centre. Harbour has no IBNR feed in this extract (ibnr is zero) and no region dimension (region_name is the postcode area). Use measure loss_ratio for loss-ratio questions; peril_code describes claims only.'
WITH METRICS
LANGUAGE YAML
AS $$
version: 0.1

source: lr_serverless_aws_us_catalog.bricksurance_semantics.harbour_loss_ratio_components

dimensions:
  - name: accident_quarter
    expr: accident_quarter
  - name: motor_segment
    expr: motor_segment
  - name: motor_segment_code
    expr: motor_segment_code
  - name: region_name
    expr: region_name
  - name: peril_code
    expr: peril_code
  - name: large_loss_flag
    expr: large_loss_flag
  - name: component_kind
    expr: component_kind

measures:
  - name: earned_premium
    expr: SUM(earned_premium)
  - name: written_premium
    expr: SUM(written_premium)
  - name: vehicle_years
    expr: SUM(vehicle_years)
  - name: claims_paid
    expr: SUM(claims_paid)
  - name: case_reserves
    expr: SUM(case_reserves)
  - name: recoveries
    expr: SUM(recoveries)
  - name: claims_handling_costs
    expr: SUM(claims_handling_costs)
  - name: incurred_claims
    expr: SUM(claims_paid) + SUM(case_reserves) + SUM(ibnr) - SUM(recoveries)
  - name: loss_ratio
    expr: (SUM(claims_paid) + SUM(case_reserves) + SUM(ibnr) - SUM(recoveries)) / NULLIF(SUM(earned_premium), 0)
  - name: claim_count
    expr: SUM(claim_count)
  - name: frequency
    expr: SUM(claim_count) / NULLIF(SUM(vehicle_years), 0)
  - name: severity
    expr: (SUM(claims_paid) + SUM(case_reserves) - SUM(recoveries)) / NULLIF(SUM(claim_count), 0)
$$;
